package net.civeira.phylax.feature.oauth.client.domain;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Collection;
import java.util.Optional;
import java.util.Set;

/**
 * Matching of a requested {@code redirect_uri} against the registered ones (task 0.10).
 *
 * <p>
 * A redirect matches only when it is <b>exactly</b> a registered URI. The single exception is a
 * loopback development URI registered with a trailing {@code /*} (for example
 * {@code http://localhost:4200/*}): the request is then parsed and must use {@code http}, the same
 * loopback host, the registered port (any port when none was registered, RFC 8252 §7.3) and a path
 * inside the registered one, without userinfo or fragment. A bare {@code *} or a {@code /*} on any
 * other host never matches.
 */
public final class RedirectUriPolicy {

  private static final Set<String> LOOPBACK = Set.of("localhost", "127.0.0.1", "[::1]");
  private static final String WILDCARD = "/*";

  private RedirectUriPolicy() {}

  /**
   * Whether the requested redirect is registered.
   *
   * @param registered registered redirect URIs
   * @param requested redirect of the request
   * @return true when it matches one of them
   */
  public static boolean allows(Collection<String> registered, String requested) {
    return requested != null && !requested.isBlank()
        && registered.stream().anyMatch(allowed -> matches(allowed, requested));
  }

  /**
   * Whether the requested redirect matches one registered URI.
   *
   * @param registered registered redirect URI
   * @param requested redirect of the request
   * @return true for an exact match or an allowed loopback match
   */
  public static boolean matches(String registered, String requested) {
    if (registered == null || requested == null) {
      return false;
    }
    if (registered.equals(requested)) {
      return !registered.contains("*");
    }
    return registered.endsWith(WILDCARD) && loopbackMatch(registered, requested);
  }

  private static boolean loopbackMatch(String registered, String requested) {
    Optional<URI> base = parse(registered.substring(0, registered.length() - 1));
    Optional<URI> asked = parse(requested);
    if (base.isEmpty() || asked.isEmpty()) {
      return false;
    }
    URI allowed = base.get();
    URI uri = asked.get();
    if (!"http".equals(allowed.getScheme()) || !LOOPBACK.contains(host(allowed))) {
      return false;
    }
    if (!"http".equals(uri.getScheme()) || !host(allowed).equals(host(uri))
        || uri.getRawUserInfo() != null || uri.getRawFragment() != null) {
      return false;
    }
    if (allowed.getPort() != -1 && allowed.getPort() != uri.getPort()) {
      return false;
    }
    String prefix =
        allowed.getRawPath() == null || allowed.getRawPath().isEmpty() ? "/" : allowed.getRawPath();
    String path = uri.getRawPath() == null || uri.getRawPath().isEmpty() ? "/" : uri.getRawPath();
    // The path stays inside the registered one, by whole segments and without dot segments.
    return path.startsWith(prefix) && !path.contains("/../") && !path.endsWith("/..")
        && !path.contains("/./");
  }

  private static String host(URI uri) {
    String host = uri.getHost();
    return host == null ? "" : host.toLowerCase();
  }

  private static Optional<URI> parse(String value) {
    try {
      URI uri = new URI(value);
      return uri.isAbsolute() && uri.getHost() != null ? Optional.of(uri) : Optional.empty();
    } catch (URISyntaxException ex) {
      return Optional.empty();
    }
  }
}
